insomnia.test('Health check returns 200 ok', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  const body = insomnia.response.json();
  insomnia.expect(body.status).to.eql('ok');
});

insomnia.test('Message sent with default chat_id', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  const body = insomnia.response.json();
  insomnia.expect(body.ok).to.eql(true);
  insomnia.expect(body.message_id).to.be.a('number');
});

insomnia.test('Message sent with custom chat_id and HTML', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  const body = insomnia.response.json();
  insomnia.expect(body.ok).to.eql(true);
  insomnia.expect(body.message_id).to.be.a('number');
});

insomnia.test('Get chat returns metadata', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  const body = insomnia.response.json();
  insomnia.expect(body.ok).to.eql(true);
  insomnia.expect(body.id).to.be.a('number');
  insomnia.expect(body.chat_type).to.be.a('string');
});

insomnia.test('Create invite link returns URL', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
  const body = insomnia.response.json();
  insomnia.expect(body.ok).to.eql(true);
  insomnia.expect(body.invite_link).to.include('https://');
});

insomnia.test('Channel created via MTProto', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
  const body = insomnia.response.json();
  insomnia.expect(body.ok).to.eql(true);
  insomnia.expect(body.chat_type).to.eql('channel');
  insomnia.expect(body.id).to.be.a('number');
});

insomnia.test('Supergroup created via MTProto', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
  const body = insomnia.response.json();
  insomnia.expect(body.ok).to.eql(true);
  insomnia.expect(body.chat_type).to.eql('supergroup');
  insomnia.expect(body.id).to.be.a('number');
});

